style.css:
@-moz-document domain("roblox.com") {
html, body {
    background: #eadfff !important;
  }

  #content {
    background-color: #eadfff !important;
    background-image:
      linear-gradient(
        rgba(234, 223, 255, 0.12),
        rgba(234, 223, 255, 0.12)
      ),
      url("https://i.postimg.cc/66r6CHGR/hoshino-dream-smaller-(1).jpg") !important;

    background-size: cover !important;
    background-position: center top !important;
    background-repeat: no-repeat !important;
    background-attachment: fixed !important;
    min-height: 100vh !important;
  }

  button,
  [role="button"],
  .btn-common {
    background-color: #d8baff !important;
    border-color: #c49aff !important;
    color: #ffffff !important;
  }

  button:hover,
  [role="button"]:hover,
  .btn-common:hover {
    background-color: #c49aff !important;
  }
}
